import type {Client,CheckpointSummary} from '@actql/sdk';
import type {ReadTicket} from './read-model.js';
export type CheckpointPageModel=Readonly<{items:readonly CheckpointSummary[];next?:string}>;
export type ReviewObservation=Readonly<{checkpoint:CheckpointSummary;artifactCid:string;byteLength:number;contentBase64:string}>;
export const checkpointReadLimits:Readonly<{maxItems:32;maxReviewBytes:65536;maxWireBytes:65536;maxNodes:10000;maxDepth:64}>;
export function checkpointPageModel(value:unknown):CheckpointPageModel;
export function captureCheckpoint(value:unknown):CheckpointSummary;
export function validReviewObservation(value:unknown,checkpoint:unknown):value is ReviewObservation;
export function readWaitingCheckpoints(client:Partial<Pick<Client,'checkpoints'>>,ticket:ReadTicket):Promise<CheckpointPageModel>;
export function readCheckpointReview(client:Partial<Pick<Client,'reviewCheckpoint'>>,checkpoint:CheckpointSummary,ticket:ReadTicket):Promise<ReviewObservation>;
export function reviewText(value:ReviewObservation):Readonly<{kind:'utf8';text:string}|{kind:'binary';base64:string}>;
export type CheckpointPanelProps=Readonly<{page:CheckpointPageModel|null;review:ReviewObservation|null;pending:boolean;
 canList:boolean;canRead:boolean;onList:()=>void;onRead:(checkpoint:CheckpointSummary)=>void}>;
